def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str) -> int | None:
        if token and token.isascii() and token.isdigit():
            return int(token)
        return None

    for i, op in enumerate(ops):
        parts = op.split(" ")
        if "" in parts:
            rejected.append(i)
            continue

        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acc, amount = parts[1], parse_amount(parts[2])
            if amount is not None and acc not in balances:
                balances[acc] = amount
                history.append(("open", acc))
            else:
                rejected.append(i)

        elif verb == "deposit" and n_parts == 3:
            acc, amount = parts[1], parse_amount(parts[2])
            if amount is not None and amount > 0 and acc in balances:
                balances[acc] += amount
                history.append(("deposit", acc, amount))
            else:
                rejected.append(i)

        elif verb == "withdraw" and n_parts == 3:
            acc, amount = parts[1], parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amount
            ):
                balances[acc] -= amount
                history.append(("withdraw", acc, amount))
            else:
                rejected.append(i)

        elif verb == "transfer" and n_parts == 4:
            src, dst, amount = parts[1], parts[2], parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
            else:
                rejected.append(i)

        elif verb == "freeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
            else:
                rejected.append(i)

        elif verb == "unfreeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
            else:
                rejected.append(i)

        elif verb == "undo" and n_parts == 1:
            if not history:
                rejected.append(i)
            else:
                last = history.pop()
                kind = last[0]
                if kind == "open":
                    del balances[last[1]]
                elif kind == "deposit":
                    balances[last[1]] -= last[2]
                elif kind == "withdraw":
                    balances[last[1]] += last[2]
                elif kind == "transfer":
                    balances[last[1]] += last[3]
                    balances[last[2]] -= last[3]
                elif kind == "freeze":
                    frozen.remove(last[1])
                elif kind == "unfreeze":
                    frozen.add(last[1])

        else:
            rejected.append(i)

    return balances, rejected
